// === ESTRUCTURA DEL PATRÓN MEMENTO ===

// 1. Memento (objeto opaco)
class TextDocumentMemento {
  constructor(
    private readonly content: string,
    private readonly cursorPos: number,
    private readonly timestamp: number
  ) {}

  // Solo el originator puede acceder a estos métodos
  getContent(): string { return this.content; }
  getCursorPos(): number { return this.cursorPos; }
  getTimestamp(): number { return this.timestamp; }
}

// 2. Originator (crea y restaura mementos)
class TextDocument {
  private content = '';
  private cursorPos = 0;

  type(text: string) {
    this.content += text;
    this.cursorPos += text.length;
  }

  save(): TextDocumentMemento {
    return new TextDocumentMemento(
      this.content,
      this.cursorPos,
      Date.now()
    );
  }

  restore(memento: TextDocumentMemento) {
    this.content = memento.getContent();
    this.cursorPos = memento.getCursorPos();
  }
}

// 3. Caretaker (almacena mementos)
class History {
  private mementos: TextDocumentMemento[] = [];

  push(memento: TextDocumentMemento) {
    this.mementos.push(memento);
  }

  pop(): TextDocumentMemento | undefined {
    return this.mementos.pop();
  }
}

// Uso:
const doc = new TextDocument();
const history = new History();

doc.type('Hola ');
history.push(doc.save());

doc.type('Mundo!');
console.log(doc); // → 'Hola Mundo!'

doc.restore(history.pop()!);
console.log(doc); // → 'Hola '

