// 1. Memento opaco
class DocumentMemento {
  constructor(
    private readonly content: string,
    private readonly cursorPos: number,
    private readonly timestamp: number
  ) {}
  getContent(): string { return this.content; }
  getCursorPos(): number { return this.cursorPos; }
}

// 2. Originator crea y restaura mementos
class Document {
  private content = '';
  private cursorPos = 0;

  save(): DocumentMemento {
    return new DocumentMemento(this.content, this.cursorPos, Date.now());
  }

  restore(m: DocumentMemento) {
    this.content = m.getContent();
    this.cursorPos = m.getCursorPos();
  }
}

// 3. Caretaker solo almacena
class History {
  private stack: DocumentMemento[] = [];
  push(m: DocumentMemento) { this.stack.push(m); }
  pop(): DocumentMemento | undefined { return this.stack.pop(); }
}

